 const paths={meter:'<rect x="6" y="3" width="20" height="26" rx="3"/><path d="M10 8h12v7H10zM11 21h2m6 0h2M11 25h10"/>',network:'<circle cx="16" cy="6" r="3"/><circle cx="6" cy="25" r="3"/><circle cx="26" cy="25" r="3"/><path d="m14 9-6 13m10-13 6 13M9 25h14"/>',chip:'<rect x="7" y="7" width="18" height="18" rx="3"/><path d="M12 1v6m8-6v6M12 25v6m8-6v6M1 12h6m-6 8h6m18-8h6m-6 8h6M12 12h8v8h-8z"/>',chart:'<path d="M4 3v25h25M9 23v-8m7 8V7m7 16V11"/>',shield:'<path d="m16 3 11 4v9c0 7-11 13-11 13S5 23 5 16V7zM10 15l4 4 8-9"/>',grid:'<path d="M4 28h24M7 28V7h18v21M11 12h3m4 0h3m-10 6h3m4 0h3m-10 6h3m4 0h3"/>',energy:'<path d="m19 2-13 17h9l-2 11 13-18h-9z"/>',battery:'<rect x="3" y="8" width="24" height="17" rx="2"/><path d="M27 13h3v7h-3M9 16h6m-3-3v6m7-3h4"/>',water:'<path d="M16 2S5 15 5 21a11 11 0 0 0 22 0C27 15 16 2 16 2zM10 21a6 6 0 0 0 6 6"/>',sun:'<circle cx="16" cy="16" r="7"/><path d="M16 1v4m0 22v4M1 16h4m22 0h4M5 5l3 3m16 16 3 3M27 5l-3 3M8 24l-3 3"/>',wallet:'<rect x="3" y="7" width="26" height="21" rx="3"/><path d="m5 7 18-5v5m6 7H18v8h11m-7-4h1"/>',factory:'<path d="M3 28V13l9 5V9l9 7V4h7v24zM7 23h2m7 0h2m6 0h2"/>',flame:'<path d="M18 2c2 10-7 10-3 17 0-6 7-5 8-11 11 16 2 23-7 23C2 31-1 17 9 9c-1 8 3 7 4 9C10 8 17 8 18 2z"/>',download:'<path d="M16 3v18m-7-7 7 7 7-7M4 22v7h24v-7"/>'};
