function standards(p){const text=[p.title,p.summary,...p.features||[],...(p.tables||[]).flat(2)].join(' ');return [...new Set([/\bIEC\b/i.test(text)?'IEC':'',/\bANSI\b/i.test(text)?'ANSI':'',/\bMID\b/i.test(text)?'MID':'',/DLMS|COSEM/i.test(text)?'DLMS / COSEM':'',/\bSTS\b/i.test(text)?'STS':''].filter(Boolean))].join('|');}
function description(p){
 const value=[p.subtitle,p.summary,p.description].find(t=>t&&String(t).trim()&&!/Explore this product in Wasion[’']s published catalog/i.test(t));
 return value||`${catalogInfo[p.catalog]?.[0]||'Product'} portfolio · ${p.title}`;
}
function productNarrative(p){
 const normalise=t=>String(t??'').trim().replace(/\s+/g,' ').toLowerCase();
 const represented=[p.title,p.subtitle,p.summary,p.description,...p.features||[],...(p.tables||[]).flat(2)].map(normalise).filter(Boolean);
 const seen=new Set();
 return (p.paragraphs||[]).filter(t=>{const n=normalise(t);if(!n||seen.has(n)||represented.some(v=>v.includes(n)))return false;seen.add(n);return true;});
}
function listing(c,slug){
 const leaf=c.leafCategories.find(p=>p.slug===slug);
 const catalog=aliases[slug]||leaf?.catalog||slug;
 const info=catalogInfo[catalog];
 if(!info&&slug!=='products')return null;
 let products=unique(c.products).filter(p=>slug==='products'||p.catalog===catalog);
 if(leaf)products=products.filter(p=>leaf.productIds.includes(p.id));
 const source=c.page(catalog==='digital-grid-distribution-monitoring'?'intelligent-power-distribution':catalog==='energy-storage'?'renewable-energy':catalog);
 const title=leaf?.label||(slug==='products'?'Product Portfolio':info[0]);
 const externalModels=(leaf?.externalModels||[]).map(p=>({id:'external-'+p.model,title:p.title,subtitle:p.subtitle,summary:p.subtitle,description:p.subtitle,catalog,features:p.features||[],tables:p.tables||[],image:p.images?.[0]?.localAsset||p.images?.[0]?.url||'',url:p.sourceURL,externalModel:true}));
 const items=[...products,...externalModels].map(p=>({...p,cataloglabel:catalogInfo[p.catalog]?.[0]||p.catalog,standard:standards(p),productfocus:p.type==='Published portfolio'?'Published portfolio':p.type,description:description(p)}));
 const leaves=c.leafCategories.filter(p=>p.catalog===catalog);
 const facets=[...(slug==='products'?[['cataloglabel','Portfolio']]:[]),...(items.some(p=>p.standard)?[['standard','Published standard']]:[]),...(new Set(items.map(p=>p.productfocus)).size>1?[['productfocus','Product focus']]:[])];
 return c.hero(title,leaf?'Explore this model family in the published Wasion portfolio.':slug==='products'?'Find the model, product family or application you need.':info[1],c.image(source),{eyebrow:'Our offering / Product portfolio',parent:[slug==='products'?'our-offering':info[2],slug==='products'?'Our offering':info[2]==='electricity-metering-data-management'?'Electricity Metering & Data Management':'Our offering'],compact:true})+
 c.section('catalogue',`${leaves.length?`<details class="wr-b-category-nav"${leaf?'':' open'}><summary>Browse product families</summary><nav aria-label="Product families">${c.link(catalog,'All '+info[0],'wr-b-category-pill')}${leaves.map(l=>c.link(l.slug,l.label,`wr-b-category-pill${leaf?.slug===l.slug?' is-active':''}`)).join('')}</nav></details>`:''}`+c.filterList({items,facets,name:'products',pageSize:6,layout:'product-rows',render:p=>`<a class="wr-b-product-row" href="${c.e(p.externalModel?encodeURI(p.url):c.h(p.slug))}"${p.externalModel?' target="_blank" rel="noopener noreferrer"':''}><div class="wr-b-product-row-media">${photo(c,p)}</div><div><span class="wr-eyebrow">${c.e(p.cataloglabel)}</span><h2>${c.e(p.title)}</h2><p>${c.e(p.description)}</p>${p.standard?`<div class="wr-b-product-tags">${p.standard.split('|').map(s=>`<span>${c.e(s)}</span>`).join('')}</div>`:''}<span class="wr-text-link">${p.externalModel?'Official technical page — opens Wasion website':'Explore product'} ${c.icon(p.externalModel?'arrow':'forward')}</span></div><span class="wr-b-row-arrow" aria-hidden="true">↗</span></a>`})+(leaf?.externalModels?.length?`<p class="wr-note">Official technical information is available on Wasion’s website. Request the current datasheet or certificate for your selected model.</p>`:'')+(items.length?'':`<div class="wr-b-family-request"><h2>Let’s define the model you need.</h2><p>Current model information for this family is available on request. Tell us your required standard, application and configuration.</p>${c.button('contact?intent='+encodeURIComponent(title),'Request family information','secondary')}</div>`),'wr-b-catalog-section')+cta(c,'Need help selecting the right product?',title);
}
